# from app/db.py, created by L4-001 from sqlalchemy import event from sqlalchemy.engine import Engine
@event.listens_for(Engine, "connect") def _set_sqlite_pragma(dbapi_connection, connection_record): cursor = dbapi_connection.cursor() cursor.execute("PRAGMA foreign_keys=ON") cursor.close()
# This listener is registered on the Engine CLASS, so ANY engine created after app.db is # imported enforces foreign keys - including the throwaway engine this task's tests build. # # This is what makes LinkTag's foreign keys real. SQLite ignores FOREIGN KEY clauses # entirely unless this pragma is set per connection, so without it test 6 below would # insert a LinkTag pointing at a non-existent link and pass silently.
